import { test, expect } from '@playwright/test';

test.describe('Search Results Sorting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
    await page.getByRole('searchbox').fill('laptop');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');
  });

  test('should sort search results by relevance', async ({ page }) => {
    const sortDropdown = page.getByRole('combobox', { name: /sort/i });
    await sortDropdown.selectOption('relevance');

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('listitem').filter({ has: page.getByRole('link') });
    const count = await results.count();
    expect(count).toBeGreaterThan(0);

    const firstResult = results.first();
    await expect(firstResult).toBeVisible();
  });

  test('should sort search results by price', async ({ page }) => {
    const sortDropdown = page.getByRole('combobox', { name: /sort/i });
    await sortDropdown.selectOption('price');

    await page.waitForLoadState('networkidle');

    const priceElements = page.getByText(/\$\d+/);
    const firstPrice = await priceElements.first().textContent();
    expect(firstPrice).toBeTruthy();
    expect(firstPrice).toMatch(/\$\d+/);
  });

  test('should sort search results by date', async ({ page }) => {
    const sortDropdown = page.getByRole('combobox', { name: /sort/i });
    await sortDropdown.selectOption('date');

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('listitem').filter({ has: page.getByRole('link') });
    const count = await results.count();
    expect(count).toBeGreaterThan(0);

    const dateElements = page.getByText(/\d{1,2}\/\d{1,2}\/\d{4}/);
    const firstDate = await dateElements.first().textContent();
    expect(firstDate).toBeTruthy();
  });

  test('should maintain search query when changing sort order', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    const initialQuery = await searchInput.inputValue();
    expect(initialQuery).toBe('laptop');

    const sortDropdown = page.getByRole('combobox', { name: /sort/i });
    await sortDropdown.selectOption('price');

    await page.waitForLoadState('networkidle');

    const finalQuery = await searchInput.inputValue();
    expect(finalQuery).toBe(initialQuery);
  });
});
